function suggestExportRows(){const seed=suggestInput.value.normalize("NFKC").trim().toLocaleLowerCase("ja-JP"),tokens=seed.split(/\s+/u).filter(Boolean);return seed?data.keyword_inventory.filter((row)=>row.site_id===siteSelector.value).filter((row)=>{const value=row.normalized_keyword.toLocaleLowerCase("ja-JP");return suggestMode.value==="prefix"?value.startsWith(seed):suggestMode.value==="contains"?value.includes(seed):tokens.every((token)=>value.includes(token))}):[]}function questionExportRows(){const site=data.sites.find((row)=>row.site_id===siteSelector.value),topicById=new Map(data.content_topic_proposals.map((row)=>[row.proposal_id,row])),query=aiQuestionSearch.value.trim().toLocaleLowerCase("ja-JP");return(site.ai_question_candidates??[]).filter((row)=>{const topic=topicById.get(row.source_topic_id);return(aiQuestionKind.value==="all"||row.candidate_kind===aiQuestionKind.value)&&(!query||`${row.question_text} ${topic?.display_topic??""}`.toLocaleLowerCase("ja-JP").includes(query))}).map((row)=>({...row,source_topic:topicById.get(row.source_topic_id)?.display_topic??null}))}function syncResearchUrl(kind){const url=new URL(location.href);if(kind==="suggest"){suggestInput.value?url.searchParams.set("suggest_q",suggestInput.value):url.searchParams.delete("suggest_q");suggestMode.value!=="prefix"?url.searchParams.set("suggest_mode",suggestMode.value):url.searchParams.delete("suggest_mode")}else{aiQuestionSearch.value?url.searchParams.set("question_q",aiQuestionSearch.value):url.searchParams.delete("question_q");aiQuestionKind.value!=="all"?url.searchParams.set("question_kind",aiQuestionKind.value):url.searchParams.delete("question_kind")}history.replaceState(null,"",url)}
