function executeUtility(){const summary=document.querySelector("#utility-summary");try{if(utilityMode.value==="replace"&&!utilitySearch.value)throw new Error("置換前の文字列を入力してください");let rows;if(utilityMode.value==="local"){const keywords=[...new Set(utilityLeft.value.split(/\r?\n/u).map((value)=>value.trim()).filter(Boolean))];if(!keywords.length)throw new Error("リストAへ元キーワードを入力してください");let selected;if(localityScope.value==="prefecture")selected=locationData.prefectures.filter((row)=>localityPrefecture.value==="all"||row.name===localityPrefecture.value).map((row)=>row.name);else if(localityScope.value==="municipality")selected=locationData.municipalities.filter((row)=>localityPrefecture.value==="all"||row.prefecture===localityPrefecture.value).map((row)=>row.municipality);else selected=locationData.stations.map((row)=>`${row.name}駅`);if(keywords.length*selected.length>20000)throw new Error("生成上限20,000行です。キーワードまたは地域粒度を絞り込んでください");rows=keywords.flatMap((keyword)=>selected.map((place)=>`${keyword} ${place}`));const provenance=localityScope.value==="station"?`国交省 ${locationData.station_source.dataset_year}年度版`:`日本郵便 ${locationData.source.updated_at}版`;summary.innerHTML=`<strong>${yen.format(rows.length)}行</strong><span>${escapeHtml(provenance)} · ${yen.format(selected.length)}地域 · digest ${escapeHtml(locationData.evidence_digest.slice(0,12))}</span>`}else{rows=runKeywordUtility(utilityMode.value,utilityLeft.value,utilityRight.value,{search:utilitySearch.value,replacement:utilityReplacement.value});summary.innerHTML=`<strong>${yen.format(rows.length)}行</strong><span>ブラウザ内処理・通信なし・DB保存なし</span>`}utilityResult.value=rows.join("\n")}catch(error){summary.innerHTML=`<strong>実行できません</strong><span>${escapeHtml(error.message)}</span>`}}
document.querySelector("#utility-run").addEventListener("click",executeUtility);document.querySelector("#utility-copy").addEventListener("click",async()=>{await navigator.clipboard.writeText(utilityResult.value);document.querySelector("#utility-summary").innerHTML=`<strong>コピー済み</strong><span>${yen.format(utilityResult.value?utilityResult.value.split(/\r?\n/u).length:0)}行</span>`});
function renderSitePortfolio(){const query=portfolioSearch.value.trim().toLocaleLowerCase("ja-JP"),rows=data.sites.filter((site)=>!query||`${site.label} ${site.domain}`.toLocaleLowerCase("ja-JP").includes(query)),totals=rows.reduce((sum,site)=>{const metrics=site.portfolio_metrics;sum.keywords+=metrics.keyword_count;sum.acquired+=metrics.serp_acquired_keyword_count;sum.cost+=metrics.provider_cost_usd;return sum},{keywords:0,acquired:0,cost:0});document.querySelector("#portfolio-metrics").innerHTML=[["登録site",rows.length],["元KW",totals.keywords],["SERP取得",totals.acquired],["provider費用$",totals.cost.toFixed(4)]].map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${typeof value==="number"?"件":""}</small></div>`).join("");portfolioRows.innerHTML=rows.map((site)=>{const metrics=site.portfolio_metrics,coverage=metrics.serp_coverage_rate==null?"—":`${(metrics.serp_coverage_rate*100).toFixed(2)}%`;return`<tr class="${site.site_id===siteSelector.value?"selected":""}"><td><strong>${escapeHtml(site.label)}</strong><small class="cell-note">${escapeHtml(site.domain)} · ${escapeHtml(site.status)}</small></td><td>${yen.format(metrics.keyword_count)}</td><td>${yen.format(metrics.serp_acquired_keyword_count)}<small class="cell-note">${coverage} / 未取得 ${yen.format(metrics.serp_unacquired_keyword_count)}</small></td><td>${metrics.resolved_group_count}/${metrics.group_count}</td><td>${metrics.task_count}</td><td>${metrics.wp_article_count}</td><td>${metrics.gsc_query_count}</td><td>${metrics.competitor_page_count}</td><td>${metrics.question_candidate_count}</td><td>$${Number(metrics.provider_cost_usd).toFixed(4)}</td><td><button class="portfolio-open detail-button" type="button" data-site="${escapeHtml(site.site_id)}">開く</button></td></tr>`}).join("");portfolioRows.querySelectorAll(".portfolio-open").forEach((button)=>button.addEventListener("click",()=>{activateSite(button.dataset.site);activateView("keywords")}));const empty=document.querySelector("#portfolio-empty");empty.hidden=rows.length>0;empty.innerHTML=rows.length?"":"<strong>登録siteなし</strong><span>未登録サイトを0件として比較表へ混ぜません。</span>"}
function renderEmptyViews(){const siteId=siteSelector.value,articles=data.gsc_articles.filter((row)=>row.site_id===siteId),articleById=new Map(data.article_query_summaries.filter((row)=>row.site_id===siteId).map((row)=>[row.wp_article_id,row])),allLinks=data.wp_observed_links.filter((row)=>row.site_id===siteId),internal=allLinks.filter((row)=>row.is_internal),resolved=internal.filter((row)=>row.target_wp_article_id!=null),opportunities=data.internal_link_opportunities.filter((row)=>articleById.has(row.source_wp_article_id)),outgoing=new Set(resolved.map((row)=>row.source_wp_article_id)),incoming=new Set(resolved.map((row)=>row.target_wp_article_id)),orphan=articles.filter((row)=>!outgoing.has(row.wp_article_id)&&!incoming.has(row.wp_article_id));document.querySelector("#link-map-metrics").innerHTML=[["構造取得記事",data.wp_content_structures.filter((row)=>row.site_id===siteId).length],["全リンク",allLinks.length],["内部リンク",internal.length],["記事間解決",resolved.length],["リンク候補",opportunities.length],["孤立記事",orphan.length],["画像",data.wp_content_images.filter((row)=>row.site_id===siteId).length]].map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${yen.format(value)}</strong><small>件</small></div>`).join("");document.querySelector("#link-map").innerHTML=resolved.length?`<div class="notice"><span>表示は先頭500件。全${yen.format(resolved.length)}件は「現在ビューJSON」で出力できます。</span></div><div class="table-wrap"><table><thead><tr><th>リンク元記事</th><th>section</th><th>anchor</th><th>リンク先記事</th><th>証跡</th></tr></thead><tbody>${resolved.slice(0,500).map((row)=>`<tr><td><strong>WP #${row.source_wp_article_id}</strong><small class="cell-note">${escapeHtml(articleById.get(row.source_wp_article_id)?.title??"")}</small></td><td>${escapeHtml(row.source_section??"見出し前")}</td><td>${escapeHtml(row.anchor_text||"画像・空anchor")}</td><td><strong>WP #${row.target_wp_article_id}</strong><small class="cell-note">${escapeHtml(articleById.get(row.target_wp_article_id)?.title??row.resolved_url)}</small></td><td><code>${escapeHtml(row.evidence_digest.slice(0,12))}</code></td></tr>`).join("")}</tbody></table></div>${orphan.length?`<div class="notice"><span>孤立記事: ${orphan.map((row)=>`WP #${row.wp_article_id}`).join(" ／ ")}</span></div>`:""}`:`<div class="map-placeholder"><strong>${escapeHtml(data.sites.find((row)=>row.site_id===siteId)?.label??siteId)}の記事間リンクは未取得です</strong><span>構造証跡を取得後に表示します。</span></div>`;document.querySelector("#link-opportunity-map").innerHTML=opportunities.length?`<table><thead><tr><th>score</th><th>リンク元</th><th>section候補</th><th>anchor候補</th><th>リンク先</th><th>SERP共通URL</th><th>証跡</th></tr></thead><tbody>${opportunities.map((row)=>`<tr><td><strong>${row.opportunity_score.toFixed(2)}</strong></td><td>WP #${row.source_wp_article_id}<small class="cell-note">${escapeHtml(articleById.get(row.source_wp_article_id)?.title??"")}</small></td><td>${escapeHtml(row.source_section_candidate??"要選定")}</td><td>${escapeHtml(row.anchor_candidate)}</td><td>WP #${row.target_wp_article_id}<small class="cell-note">${escapeHtml(articleById.get(row.target_wp_article_id)?.title??"")}</small></td><td>${row.shared_url_count}<small class="cell-note">${row.evidence_relation_ids.length} relation</small></td><td><code>${escapeHtml(row.evidence_digest.slice(0,12))}</code></td></tr>`).join("")}</tbody></table>`:'<div class="empty"><strong>候補なし</strong><span>確定記事間の実測リンクまたはSERP関係を確認してください。</span></div>'}
function renderMarketData(){const query=marketDataSearch.value.trim().toLocaleLowerCase("ja-JP"),status=data.dfs_enrichment_status,monthlyByKeyword=new Map();for(const row of data.keyword_monthly_searches){const values=monthlyByKeyword.get(row.normalized_keyword)??[];values.push(row);monthlyByKeyword.set(row.normalized_keyword,values)}const difficultyByKeyword=new Map(data.keyword_difficulties.map((row)=>[row.normalized_keyword,row])),metrics=data.keyword_market_metrics.filter((row)=>!query||`${row.keyword} ${row.competition_level??""}`.toLocaleLowerCase("ja-JP").includes(query)),ranked=data.domain_ranked_keywords.filter((row)=>!query||`${row.keyword} ${row.main_intent??""} ${row.url??""}`.toLocaleLowerCase("ja-JP").includes(query)),summary=data.domain_ranked_keyword_summaries[0],pending=document.querySelector("#market-data-pending");document.querySelector("#market-data-metrics").innerHTML=[["取得状態",status.state==="acquired"?"取得済":"未取得"],["市場指標",data.keyword_market_metrics.length],["月次観測",data.keyword_monthly_searches.length],["難易度",data.keyword_difficulties.length],["獲得KW",data.domain_ranked_keywords.length],["全rank候補",summary?.total_count??"—"],["取得費用$",Number(status.reported_cost_usd??0).toFixed(4)]].map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${escapeHtml(value)}</strong><small>${typeof value==="number"?"件":""}</small></div>`).join("");pending.hidden=status.state==="acquired";pending.innerHTML=status.state==="acquired"?"":"<strong>追加市場データは未取得です</strong><span>現在の検索量は取込workbook由来です。課金取得は自動実行せず、poc:dfs-enrichment:planで費用とrequestを確認してから実行します。</span>";marketKeywordRows.innerHTML=metrics.map((row)=>{const months=monthlyByKeyword.get(row.normalized_keyword)??[],difficulty=difficultyByKeyword.get(row.normalized_keyword);return`<tr><td><strong>${escapeHtml(row.keyword)}</strong></td><td>${row.search_volume==null?"欠損":yen.format(row.search_volume)}</td><td>${difficulty?.keyword_difficulty??"欠損"}</td><td>${row.cpc==null?"欠損":`$${Number(row.cpc).toFixed(2)}`}</td><td>${escapeHtml(row.competition_level??"欠損")}<small class="cell-note">index ${row.competition_index??"—"}</small></td><td>${months.length}か月<small class="cell-note">${months[0]?`${months[0].year}-${String(months[0].month).padStart(2,"0")}: ${months[0].search_volume??"欠損"}`:"—"}</small></td><td>取得済み</td></tr>`}).join("");marketRankedRows.innerHTML=ranked.map((row)=>`<tr><td><strong>${escapeHtml(row.keyword)}</strong></td><td>${escapeHtml(row.main_intent??"不明")}</td><td>${row.rank_absolute??"—"}</td><td>${row.url?`<a href="${escapeHtml(row.url)}" target="_blank" rel="noreferrer">${escapeHtml(row.title??row.relative_url??row.url)}</a>`:"—"}</td><td>${row.search_volume==null?"欠損":yen.format(row.search_volume)}</td><td>${row.etv==null?"欠損":Number(row.etv).toFixed(2)}</td><td>${row.rank_changes?.is_new?"新規":row.rank_changes?.is_up?`上昇 ${row.rank_changes.previous_rank_absolute??"—"}→${row.rank_absolute??"—"}`:row.rank_changes?.is_down?`下降 ${row.rank_changes.previous_rank_absolute??"—"}→${row.rank_absolute??"—"}`:"変化なし"}</td></tr>`).join("")}
portfolioSearch.addEventListener("input",renderSitePortfolio);marketDataSearch.addEventListener("input",renderMarketData);quickSearchInput.value=requestParams.get("quick_q")??"";suggestInput.value=requestParams.get("suggest_q")??"";suggestMode.value=["prefix","contains","tokens"].includes(requestParams.get("suggest_mode"))?requestParams.get("suggest_mode"):"prefix";aiQuestionSearch.value=requestParams.get("question_q")??"";aiQuestionKind.value=["all","observed_question","derived_question"].includes(requestParams.get("question_kind"))?requestParams.get("question_kind"):"all";selectSite();renderMarketData();renderDemandSearch();renderAiQuestions();renderLexicalExplorer();renderQuickSearch();renderSuggestExplorer();renderSitePortfolio();renderResearchHistory();const requestedView=requestParams.get("view");if(document.querySelector(`.tab[data-view="${CSS.escape(requestedView??"")}"]`))activateView(requestedView);else if(location.hash==="#quick-search"||quickSearchInput.value)activateView("quick-search");else if(suggestInput.value)activateView("suggest-explorer");else if(aiQuestionSearch.value||aiQuestionKind.value!=="all")activateView("ai-questions");
